def render(context):
    exec(compile('metric_1, metric_2, metric_3, metric_4 = st.columns(4)\nmetric_1.metric(\n    "States / UTs",\n    f"{len(df)}",\n)\nmetric_2.metric(\n    "Net Installed",\n    f"{total_installed:,}",\n)\nmetric_3.metric(\n    "Operational",\n    f"{total_operational:,}",\n)\nmetric_4.metric(\n    "Operational Rate",\n    f"{operational_rate:.1f}%",\n)\nst.info(\n    "Coverage: Ministry of Heavy Industries / "\n    "Oil Marketing Companies data as on 1 March 2026. "\n    "This is not a complete inventory of all public "\n    "charging operators."\n)\nst.markdown(\'<div id="evqi-insights"></div>\', unsafe_allow_html=True)\nst.subheader("Charging Infrastructure Insights")\nst.subheader("Annual Gross OMC Charger Installations")\nannual_totals = (\n    long_df.groupby(\n        "financial_year",\n        observed=False,\n        as_index=False,\n    )["gross_installations"]\n    .sum()\n)\nannual_chart = px.bar(\n    annual_totals,\n    x="financial_year",\n    y="gross_installations",\n    title=(\n        "OMC Charger Installations by Financial Year "\n        "(FY 2025-26 is partial)"\n    ),\n    text_auto=True,\n    labels={\n        "financial_year": "Financial Year",\n        "gross_installations": "Gross Installations",\n    },\n)\nst.plotly_chart(\n    annual_chart,\n    width="stretch",\n)\nst.subheader(\n    "Top States / UTs by Operational Chargers"\n)\ntop_states = df.nlargest(\n    10,\n    "operational",\n).sort_values(\n    "operational",\n    ascending=True,\n)\ntop_chart = px.bar(\n    top_states,\n    x="operational",\n    y="state",\n    orientation="h",\n    color="operational",\n    title="Top 10 States / UTs",\n    labels={\n        "operational": "Operational Chargers",\n        "state": "State / UT",\n    },\n)\nst.plotly_chart(\n    top_chart,\n    width="stretch",\n)\nst.caption(\n    "Annual figures represent gross installations "\n    "reported for each period. Installed totals are "\n    "separate source-reported figures and may reflect "\n    "decommissioning."\n)', __file__, 'exec'), context)
